#include "EffectPresets.h"
#include <set>
static void testEffectChains(const File& root,Assets& assets){
    EffectOrder order{0,1,2,3,4,5};int permutations=0;do{EffectOrder restored;expect(validateEffectOrder(order).wasOk()&&effectOrderFromJson(effectOrderToJson(order),restored).wasOk()&&restored==order,"all permutations of the six effects roundtrip as stable identities");++permutations;}while(std::next_permutation(order.begin(),order.end()));expect(permutations==720,"effect ordering supports all 720 six-processor permutations");
    EffectOrder unchanged{5,4,3,2,1,0};for(auto invalid:{var(Array<var>{0,1,2,3,4,4}),var(Array<var>{0,1,2,3,4,6}),var(Array<var>{0,1,2,3,4}),var(Array<var>{0,1,2,3,4,5,6}),var(Array<var>{0,1,2,3,4,2.5}),var(Array<var>{0,1,2,3,4,true}),var(Array<var>{0,1,2,3,4,"5"})}){auto before=unchanged;expect(effectOrderFromJson(invalid,unchanged).failed()&&unchanged==before,"invalid effect orders fail atomically without coercing identities");}
    const auto& factory=factoryEffectChains();expect(factory.size()==8,"eight original factory effect chains are bundled locally");std::set<String> names;
    for(const auto& preset:factory){names.insert(preset.name);expect(validateEffectChain(preset).wasOk(),"factory effect chain settings and ordering are valid");EffectChainPreset read;expect(effectChainFromJson(effectChainToJson(preset),read).wasOk()&&JSON::toString(effectChainToJson(read))==JSON::toString(effectChainToJson(preset)),"factory chain JSON roundtrips all six processors and bypass states");auto song=emptyProject();song.loop=false;song.patterns[0].lanes[7]={{0,.7,60,.7f}};song.tracks[7].mixer=preset.settings;auto audio=render(song,assets,root,24000);bool finite=true;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)finite&=std::isfinite(audio.getSample(ch,i));expect(finite&&audio.getMagnitude(0,0,24000)>.001f,"every factory effect chain produces audible finite audio");}expect(names.size()==8,"factory chain names are unique");
    auto source=factory.back().settings;source.output=5;source.sidechain=0;auto personal=captureEffectChain(String::fromUTF8("My chain – Клавіші"),source);expect(personal.settings.output==-1&&personal.settings.sidechain==-1&&personal.settings.order==source.order,"capturing a chain excludes external channel references and retains order");auto json=effectChainToJson(personal);auto text=JSON::toString(json);expect(!text.contains("output")&&!text.contains("sidechain"),"portable chain files contain no mixer routing references");EffectChainPreset read;expect(effectChainFromJson(json,read).wasOk()&&read.name==personal.name,"Unicode chain names roundtrip");
    for(const char* key:{"low","mid","high","threshold","ratio","attack","release","makeup","mix","room","damping"})for(const var& invalid:{var("bad"),var(-999.),var(99999.),var(std::numeric_limits<double>::infinity())}){auto bad=effectChainToJson(personal);bad["settings"].getDynamicObject()->setProperty(key,invalid);auto before=JSON::toString(effectChainToJson(read));expect(effectChainFromJson(bad,read).failed()&&JSON::toString(effectChainToJson(read))==before,"malformed or out-of-range chain parameters fail atomically");}
    for(auto key:{"eq","compressor","reverb"}){auto bad=effectChainToJson(personal);bad["settings"].getDynamicObject()->setProperty(key,1);expect(effectChainFromJson(bad,read).failed(),"effect bypass flags cannot be coerced from arbitrary values");}
    for(auto key:{"output","sidechain"}){auto bad=effectChainToJson(personal);bad["settings"].getDynamicObject()->setProperty(key,2);expect(effectChainFromJson(bad,read).failed(),"effect presets reject routing references instead of importing foreign channels");}
    for(auto key:{"order","chorus","flanger","phaser"}){auto bad=effectChainToJson(personal);bad["settings"].getDynamicObject()->removeProperty(key);expect(effectChainFromJson(bad,read).failed(),"incomplete chain files cannot silently drop processor settings");}
    auto bad=effectChainToJson(personal);bad.getDynamicObject()->setProperty("schema",99);expect(effectChainFromJson(bad,read).failed(),"unknown effect chain schema is rejected");auto invalid=personal;invalid.name=" ";expect(validateEffectChain(invalid).failed(),"empty chain names are rejected");invalid=personal;invalid.name="Bad\nname";expect(validateEffectChain(invalid).failed(),"control characters in chain names are rejected");invalid=personal;invalid.settings.sidechain=0;expect(validateEffectChain(invalid).failed(),"unportable in-memory chain presets are rejected");
    auto file=root.getChildFile("personal.pulseeffects");expect(saveEffectChain(personal,file).wasOk()&&loadEffectChain(file,read).wasOk()&&JSON::toString(effectChainToJson(read))==JSON::toString(effectChainToJson(personal)),"local chain files save atomically and reload complete settings");auto hash=SHA256(file).toHexString();invalid=personal;invalid.settings.order={0,1,2,3,4,4};expect(saveEffectChain(invalid,file).failed()&&SHA256(file).toHexString()==hash,"invalid effect chain cannot overwrite a valid file");auto oversized=root.getChildFile("oversized.pulseeffects");oversized.replaceWithText(String::repeatedString(" ",128*1024+1));expect(loadEffectChain(oversized,read).failed(),"oversized effect chain files are bounded");auto directory=root.getChildFile("chain-directory");directory.createDirectory();expect(saveEffectChain(personal,directory).failed()&&directory.isDirectory(),"failed chain commit preserves an existing directory");
    // The same nonlinear processors sound different when their order changes.
    auto song=emptyProject();song.bpm=120;song.loop=false;song.patterns[0].length=4;song.patterns[0].lanes[7]={{0,2,48,.8f}};song.tracks[7].send=0;auto& fx=song.tracks[7].mixer;fx.eq=true;fx.low=12;fx.high=8;fx.compressor=true;fx.threshold=-28;fx.ratio=8;fx.compAttack=.1f;fx.compRelease=120;auto eqFirst=render(song,assets,root,72000,127);fx.order={1,0,2,3,4,5};auto compFirst=render(song,assets,root,72000,127);double difference=0;for(int i=0;i<72000;++i)difference+=std::abs(eqFirst.getSample(0,i)-compFirst.getSample(0,i));expect(difference>10&&compFirst.getRMSLevel(0,12000,24000)>eqFirst.getRMSLevel(0,12000,24000)*1.2f,"reordering EQ and compression changes actual nonlinear chain audio");
    auto blocks=render(song,assets,root,72000,512);bool same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i)same&=blocks.getSample(ch,i)==compFirst.getSample(ch,i);expect(same,"reordered effects are independent of callback size");RenderSettings encoding;encoding.bits=32;encoding.endBeat=3;encoding.tailSeconds=0;auto wav=root.getChildFile("reordered-effects.wav");expect(renderAudio(song,assets,root,wav,encoding).wasOk(),"reordered chains export to float WAV");String error;auto* exported=assets.load(wav,error);same=exported&&exported->audio.getNumSamples()==72000;if(same)for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i)same&=std::abs(exported->audio.getSample(ch,i)-compFirst.getSample(ch,i))<.000001f;expect(same,"offline export matches reordered callback audio sample for sample");
    auto session=root.getChildFile("ordered-chain.pulse");Project reopened;expect(saveProject(song,session).wasOk()&&loadProject(session,reopened).wasOk()&&reopened.tracks[7].mixer.order==fx.order&&reopened.patterns[0].length==4,"schema 11 persists chain order and variable pattern length");auto legacy=projectToJson(song);legacy.getDynamicObject()->setProperty("schema",10);for(auto& track:*legacy["tracks"].getArray())track["mixer"].getDynamicObject()->removeProperty("order");expect(projectFromJson(legacy,reopened).wasOk()&&reopened.tracks[7].mixer.order==EffectOrder{0,1,2,3,4,5},"schema 10 migrates to the original processing order");auto audio=render(reopened,assets,root,72000,127);same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i)same&=audio.getSample(ch,i)==eqFirst.getSample(ch,i);expect(same,"legacy migration preserves original effect-chain audio exactly");
    auto broken=projectToJson(song);(*broken["tracks"].getArray())[7]["mixer"].getDynamicObject()->removeProperty("order");auto before=JSON::toString(projectToJson(reopened));expect(projectFromJson(broken,reopened).failed()&&JSON::toString(projectToJson(reopened))==before,"schema 11 cannot silently discard effect order");hash=SHA256(session).toHexString();fx.order={0,1,2,3,4,4};expect(saveProject(song,session).failed()&&SHA256(session).toHexString()==hash,"invalid processing order cannot replace a valid saved project");auto playback=std::make_unique<Playback>();String warning;expect(compilePlayback(song,assets,root,*playback,warning).failed(),"invalid order cannot enter a callback snapshot");fx.order={1,0,2,3,4,5};ProjectTemplate info;expect(saveProjectTemplate(song,root,root.getChildFile("chain-templates"),"Ordered effects","Six processor chain",TemplateContent::complete,info).wasOk(),"ordered effects save into local templates");expect(loadProjectTemplate(info,reopened).wasOk()&&reopened.tracks[7].mixer.order==fx.order,"template recall retains processor identities and order");
}
